package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchResult struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Body  string `json:"body"`
}

// searchHandler allows users to search internal knowledge base articles
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("category")

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	// Build search query with category filter
	var sqlQuery string
	if category != "" {
		// Category is used to narrow results - concatenated for flexible matching
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, body FROM articles WHERE category = '%s' AND (title ILIKE '%%' || $1 || '%%' OR body ILIKE '%%' || $1 || '%%') AND published = true LIMIT 50",
			category,
		)
	} else {
		sqlQuery = "SELECT id, title, body FROM articles WHERE (title ILIKE '%' || $1 || '%' OR body ILIKE '%' || $1 || '%') AND published = true LIMIT 50"
	}

	rows, err := db.Query(sqlQuery, query)
	if err != nil {
		log.Printf("Search error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.ID, &r.Title, &r.Body); err != nil {
			continue
		}
		results = append(results, r)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthHandler for load balancer checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

// adminReindexHandler triggers a reindex of the search corpus
func adminReindexHandler(w http.ResponseWriter, r *http.Request) {
	// Note: auth is handled at the infrastructure layer
	table := r.URL.Query().Get("table")
	if table == "" {
		table = "articles"
	}
	// Only allow known tables
	allowed := map[string]bool{"articles": true, "comments": true, "tags": true}
	if !allowed[table] {
		http.Error(w, "Invalid table", 400)
		return
	}
	_, err := db.Exec(fmt.Sprintf("REINDEX TABLE %s", table))
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
	w.Write([]byte("reindex complete"))
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("%s %s %s remote=%s", r.Method, r.URL.Path, r.URL.RawQuery, r.RemoteAddr)
		// Strip null bytes from query params as basic sanitization
		q := r.URL.Query()
		for k, vals := range q {
			for i, v := range vals {
				q[k][i] = strings.ReplaceAll(v, "\x00", "")
			}
		}
		r.URL.RawQuery = q.Encode()
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/search", searchHandler)
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/admin/reindex", adminReindexHandler)

	handler := loggingMiddleware(mux)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}
